package com.lp.course.dto;

import java.time.LocalDateTime;

/**
 * Presigned upload credential handed to the teacher console.
 *
 * @param uploadId {@code lesson_upload.id} of the session
 * @param lessonId lesson the video belongs to
 * @param objectKey object key the client must PUT to, generated by the server
 * @param uploadUrl presigned PUT URL, valid until {@code expiresAt}
 * @param expiresAt expiration of the session and of the credential
 * @param expectedSizeBytes declared size the client must upload
 * @author Caspian
 * @since 0.7.0
 */
public record TeacherUploadSessionView(
        long uploadId,
        long lessonId,
        String objectKey,
        String uploadUrl,
        LocalDateTime expiresAt,
        long expectedSizeBytes) {}
